import{_ as s,a0 as o,w as l,s as p,ao as d,I as n,x as t,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux有问必答：如何检查MariaDB服务端版本 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何检查MariaDB服务端版本 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何检查MariaDB服务端版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何检查MariaDB服务端版本 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150821 Linux FAQs with Answers--How to check MariaDB server version","title":"Linux有问必答：如何检查MariaDB服务端版本","tag":"201508","desc":""},"relativePath":"201508/20150821 Linux FAQs with Answers--How to check MariaDB server version.md","filePath":"[post].md"}'),m={name:"201508/20150821 Linux FAQs with Answers--How to check MariaDB server version.md"};function u(h,a,f,x,b,D){const r=o("Link");return l(),p("div",null,[a[13]||(a[13]=d(`<h1 id="linux有问必答-如何检查mariadb服务端版本" tabindex="-1">Linux有问必答：如何检查MariaDB服务端版本 <a class="header-anchor" href="#linux有问必答-如何检查mariadb服务端版本" aria-label="Permalink to “Linux有问必答：如何检查MariaDB服务端版本”">​</a></h1><blockquote><p><strong>提问</strong>: 我使用的是一台运行MariaDB的VPS。我该如何检查MariaDB服务端的版本？</p></blockquote><p>有时候你需要知道你的数据库版本，比如当你升级你数据库或对已知缺陷打补丁时。这里有几种方法找出MariaDB版本的方法。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>第一种找出版本的方法是登录MariaDB服务器，登录之后，你会看到一些MariaDB的版本信息。</p><p><img src="https://farm6.staticflickr.com/5807/20669891016_91249d3239_c.jpg" alt=""></p><p>另一种方法是在登录MariaDB后出现的命令行中输入‘status’命令。输出会显示服务器的版本还有协议版本。</p><p><img src="https://farm6.staticflickr.com/5801/20669891046_73f60e5c81_c.jpg" alt=""></p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>如果你不能访问MariaDB服务器，那么你就不能用第一种方法。这种情况下你可以根据MariaDB的安装包的版本来推测。这种方法只有在MariaDB通过包管理器安装的才有用。</p><p>你可以用下面的方法检查MariaDB的安装包。</p><h4 id="debian、ubuntu或者linux-mint" tabindex="-1">Debian、Ubuntu或者Linux Mint: <a class="header-anchor" href="#debian、ubuntu或者linux-mint" aria-label="Permalink to “Debian、Ubuntu或者Linux Mint:”">​</a></h4><pre><code>$ dpkg -l | grep mariadb
</code></pre><p>下面的输出说明MariaDB的版本是10.0.17。</p><p><img src="https://farm1.staticflickr.com/607/20669890966_b611fcd915_c.jpg" alt=""></p><h4 id="fedora、centos或者-rhel" tabindex="-1">Fedora、CentOS或者 RHEL: <a class="header-anchor" href="#fedora、centos或者-rhel" aria-label="Permalink to “Fedora、CentOS或者 RHEL:”">​</a></h4><pre><code>$ rpm -qa | grep mariadb
</code></pre><p>下面的输出说明安装的版本是5.5.41。</p><p><img src="https://farm1.staticflickr.com/764/20508160748_23d9808256_b.jpg" alt=""></p><hr>`,20)),n("p",null,[a[1]||(a[1]=t("via: ",-1)),e(r,{href:"http://ask.xmodulo.com/check-mariadb-server-version.html"},{default:i(()=>[...a[0]||(a[0]=[t("http://ask.xmodulo.com/check-mariadb-server-version.html",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=t("作者：",-1)),e(r,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...a[2]||(a[2]=[t("Dan Nanni",-1)])]),_:1}),a[6]||(a[6]=t(" 译者：",-1)),e(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[3]||(a[3]=[t("geekpi",-1)])]),_:1}),a[7]||(a[7]=t(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原创翻译，",-1)),e(r,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[t("Linux中国",-1)])]),_:1}),a[12]||(a[12]=t(" 荣誉推出",-1))])])}const B=s(m,[["render",u]]);export{k as __pageData,B as default};
